import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.cyF4XceO.js";const h=JSON.parse('{"title":"Retained Provider 2.1.1 history — ObjectBucket","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/object-bucket.md","filePath":"proposals/edge/object-bucket.md"}'),d={name:"proposals/edge/object-bucket.md"};function i(c,e,n,s,l,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="retained-provider-2-1-1-history-—-objectbucket" tabindex="-1">Retained Provider 2.1.1 history — ObjectBucket <a class="header-anchor" href="#retained-provider-2-1-1-history-—-objectbucket" aria-label="Permalink to &quot;Retained Provider 2.1.1 history — ObjectBucket&quot;">​</a></h1><p>This page records the design that shipped in the retained <code>edge.forms.takoform.com/v1beta1</code> package set and Provider 2.1.1 as Terraform resource type <code>takoform_edge_object_bucket</code>. It is not a current proposal or current Form. The versionless Edge candidate has no <code>ObjectBucket</code>, no <code>edge.objects</code> Interface, no <code>module-worker.object-bucket</code> Binding, and no Provider 3 authoring identity for one.</p><p>The exact retained Definition and package bytes, not this prose, are the historical authority. They remain under <code>forms/candidates/edge/v1beta1/object-bucket</code> and in the append-only Provider identity ledger. Nothing in Specification 1.0 re-identifies or republishes them.</p><h2 id="historical-workload-and-consumer" tabindex="-1">Historical workload and consumer <a class="header-anchor" href="#historical-workload-and-consumer" aria-label="Permalink to &quot;Historical workload and consumer&quot;">​</a></h2><p>The retained Form modeled a flat-namespace object store for uploads, media, and exports. A retained Worker Version consumed it through the exact <code>module-worker.object-bucket</code> Binding.</p><h2 id="historical-role-and-semantics" tabindex="-1">Historical role and semantics <a class="header-anchor" href="#historical-role-and-semantics" aria-label="Permalink to &quot;Historical role and semantics&quot;">​</a></h2><p>Its role was <code>identity</code>. The bucket had no desired fields; its semantics were fixed by the retained <code>edge.objects@1.0.0</code> Interface. That contract described head/get/put/delete/list plus four multipart operations, strong read-after-write consistency, last-writer-wins per key, strong etags with conditional reads and writes, and cursor pagination with delimiter roll-up.</p><p>Bodies streamed beside operation documents. <code>get</code> and <code>put</code> carried <code>bodyStream</code> and <code>contentLength</code>; ranged and conditional reads were typed inputs of <code>get</code>. Objects above <code>maxSinglePutBytes</code>, or of unknown size, used <code>createMultipartUpload</code>, <code>uploadPart</code>, <code>completeMultipartUpload</code>, and <code>abortMultipartUpload</code> (decision 0020).</p><p>The original separate-Form boundary treated CORS, lifecycle expiry, retention lock, eventual consistency, and object versioning as different contracts. A live retained binding also made deletion fail with <code>dependency_in_use</code>.</p><p>These statements describe the retained v1beta1 identity only. They do not define a current object-resource lifecycle or certify an external object service.</p><h2 id="current-object-service-boundary" tabindex="-1">Current object-service boundary <a class="header-anchor" href="#current-object-service-boundary" aria-label="Permalink to &quot;Current object-service boundary&quot;">​</a></h2><p>Current worker code may request an externally managed S3-compatible service through a sealed <code>externalServices</code> slot. The slot carries <code>standards.takoform.com/v1</code> and an opaque reverse-DNS protocol identifier such as <code>com.amazonaws.s3</code>. Takoform does not enumerate protocol identifiers, provision a bucket Resource, expose endpoints or credentials in portable state, or certify that a service conforms to the named protocol. The Host owns support lookup and sealed runtime projection.</p><p>That call-only standard-service boundary is intentionally not a replacement <code>ObjectBucket</code> Form. A future portable object Resource would require its own explicit Form decision and identity; it cannot inherit this retained one.</p>',13)])])}const b=o(d,[["render",i]]);export{h as __pageData,b as default};
